let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = {};
}
return [{ json: { plan: parsed.plan ?? '' } }];

let attemptCount = 1;
let retryFeedback = '';
try {
  const reviewerRuns = $('Parse Reviewer Output').all();
