    const latest = reviewerRuns[reviewerRuns.length - 1].json;
    attemptCount = latest.nextAttemptCount;
    retryFeedback = '\n\nThis is attempt ' + attemptCount + ' of at most 3. Your previous diff was:\n' + (latest.previousDiff || '(empty - no diff was produced)') + '\n\nThe Reviewer rejected it because: ' + latest.reason + '\n\nSpecific feedback: ' + latest.feedbackForCoder + '\n\nFix this issue in your next diff.';
  }
} catch (e) {
  // Parse Reviewer Output has not run yet in this execution - first attempt.
}

const userContent = "Task: " + $('Prepare Row').item.json.task_description + "\n\nPlan:\n" + $('Parse Plan').item.json.plan + "\n\nCurrent repository file contents:\n" + ($('Fetch File Context').item.json.stdout ?? '(none found)') + retryFeedback;

return [{ json: { userContent, attemptCount } }];

