  }
}

if (hunk.length > 0 && !hunk.endsWith('\n')) {
  hunk = hunk + '\n';
}

const fileContextText = $('Fetch File Context').item.json.stdout ?? '';
let existingLines = null;
if (file) {
  let markerIdx = fileContextText.indexOf('=== ' + file + ' ===');
  let markerLen = ('=== ' + file + ' ===').length;
  if (markerIdx === -1) {
    markerIdx = fileContextText.indexOf('=== ./' + file + ' ===');
    markerLen = ('=== ./' + file + ' ===').length;
  }
  if (markerIdx !== -1) {
    const afterMarker = fileContextText.slice(markerIdx + markerLen + 1);
    const nextMarkerIdx = afterMarker.indexOf('\n=== ');
    const existingContent = (nextMarkerIdx === -1 ? afterMarker : afterMarker.slice(0, nextMarkerIdx)).replace(/\n$/, '');
    existingLines = existingContent.split('\n');
  }
}

// A hunk body that's exclusively "+" lines matches the "model assumed a
// brand-new file" shape. Real, observed bug this replaces: the previous
// version rebuilt EVERY existing-file case this way, even when the model
// had already produced a perfectly valid hunk with real context/removed
// lines (which the shared count-fix above already correctly recomputes) -
// discarding good output and replacing it with a stripped-down,
// context-free append that only coincidentally happened to still work
// sometimes. Only the genuine "all-additions but file already exists"
// mismatch needs rebuilding; a hunk that already has context or removed
// lines just needs the standard header, which the shared repairs already
// prepared correctly.
const bodyLinesForCheck = hunk
  .split('\n')
  .slice(1)
  .filter((l, idx, arr) => !(idx === arr.length - 1 && l === ''));
const isAllAdditions = bodyLinesForCheck.length > 0 && bodyLinesForCheck.every((l) => l.startsWith('+'));

let diff = '';
if (!file || !hunk) {
  diff = '';
} else if (existingLines === null) {
  // Genuinely a new file - keep the model's own hunk as-is (should already
  // be an all-"+" @@ -0,0 hunk; the shared count-fix above already
  // corrected its counts if needed).
  diff = '--- /dev/null\n+++ b/' + file + '\n' + hunk;
} else if (!isAllAdditions) {
  // Model already correctly represented existing content with context/
  // removed lines - just needs the standard existing-file header.
  diff = '--- a/' + file + '\n+++ b/' + file + '\n' + hunk;
} else {
  // Model incorrectly assumed a brand-new file even though it exists -
  // rebuild as a proper append, dropping any lines that are actually just
  // the existing content redundantly echoed back as "+".
  const addedLines = bodyLinesForCheck.map((l) => l.slice(1));
  let i = 0;
  while (i < existingLines.length && i < addedLines.length && addedLines[i] === existingLines[i]) i++;
  const genuinelyNew = addedLines.slice(i);
  if (genuinelyNew.length === 0) {
    diff = ''; // nothing new to add - treat as a no-op, not a broken patch
  } else {
    const existingCount = existingLines.length;
    const newHunkHeader = '@@ -' + existingCount + ',0 +' + (existingCount + 1) + ',' + genuinelyNew.length + ' @@';
    const newBlock = genuinelyNew.map((l) => '+' + l).join('\n') + '\n';
    diff = '--- a/' + file + '\n+++ b/' + file + '\n' + newHunkHeader + '\n' + newBlock;
  }
}
return [{ json: { diff } }];

const coderDiff = ($('Parse Coder Output').item.json.diff || '').trim();
const testDiff = ($json.diff || '').trim();
const combined = [coderDiff, testDiff].filter(Boolean).join('\n');
return [{ json: { combinedDiff: combined } }];

