={{ JSON.stringify({
  model: "qwen3:8b",
  stream: false,
  messages: [
    { role: "system", content: "You are the Reviewer for a coding task. You are given the task, the combined diff that was applied, and the actual sandbox test result (exit code, stdout, stderr). Decide one of:\n- \"approve\": the diff correctly implements the task and the tests genuinely pass (exit code 0, no test failures visible in the output).\n- \"retry\": there's a specific, fixable problem worth another attempt - e.g. the diff didn't apply cleanly, a test failure reveals incorrect logic, or the diff broke something (a syntax error, a missing line).\n- \"give_up\": retrying seems unlikely to help - e.g. the task itself seems ambiguous, contradictory, or infeasible given the repository shown.\nGive a clear \"reason\" for your verdict. If verdict is \"retry\", \"feedback_for_coder\" must describe exactly what went wrong and what to do differently - be specific, quote the actual error if there is one." },
    { role: "user", content: "Task: " + $('Prepare Row').item.json.task_description + "\n\nCombined diff that was applied:\n" + $('Combine Diffs').item.json.combinedDiff + "\n\nSandbox result:\nexit code: " + $json.exitCode + (($json.timedOut) ? ' (timed out)' : '') + "\nstdout:\n" + ($json.stdout || '') + "\nstderr:\n" + ($json.stderr || '') }
  ],
  format: {
    type: "object",
    properties: {
      verdict: { type: "string", enum: ["approve", "retry", "give_up"] },
      reason: { type: "string" },
      feedback_for_coder: { type: "string" }
    },
    required: ["verdict", "reason", "feedback_for_coder"]
  }
}) }}

parameters.jsCode:
let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  parsed = { verdict: 'give_up', reason: 'Reviewer response was not valid JSON', feedback_for_coder: '' };
}
const sandboxResult = $('Sandbox Execute').item.json;
const attemptCount = $('Build Coder Prompt').item.json.attemptCount;
return [{ json: {
  verdict: parsed.verdict === 'approve' || parsed.verdict === 'retry' ? parsed.verdict : 'give_up',
  reason: parsed.reason ?? '',
  feedbackForCoder: parsed.feedback_for_coder ?? '',
  attemptCount,
  nextAttemptCount: attemptCount + 1,
  previousDiff: $('Combine Diffs').item.json.combinedDiff,
  exitCode: sandboxResult.exitCode,
  stdout: sandboxResult.stdout,
  stderr: sandboxResult.stderr,
  timedOut: sandboxResult.timedOut,
} }];

const taskDescription = $('Prepare Row').item.json.task_description;
const slug = taskDescription
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 40);
const branchName = 'coding-agent/' + slug + '-' + Date.now();

return [{ json: {
  branchName,
  commitMessage: taskDescription.slice(0, 72),
  prTitle: '[coding-agent] ' + taskDescription.slice(0, 60),
  prBody: 'Automated change proposed by the coding-agent pipeline.\n\nTask: ' + taskDescription + '\n\nReviewer notes: ' + ($json.reason || ''),
} }];

const reviewerData = $('Parse Reviewer Output').item.json;
return [{ json: {
  ...reviewerData,
  prUrl: $json.prUrl || null,
  prError: $json.error || null,
} }];
